import django_rq
from django.http import JsonResponse, HttpResponseForbidden
from django.contrib.auth.decorators import login_required

@login_required
def peek_queue_jobs_view(request, queue_name):
    # Only platform superusers or designated queue staff may inspect general queue internals
    if not request.user.is_staff:
        return HttpResponseForbidden('Staff privileges required to view queue internals')

    offset = int(request.GET.get('offset', 0))
    length = min(int(request.GET.get('length', 20)), 50)
    queue = django_rq.get_queue(queue_name)
    jobs = queue.get_jobs(offset, length)

    results = []
    for job in jobs:
        results.append({
            'id': job.id,
            'created_at': job.created_at.isoformat() if job.created_at else None,
            'description': job.description,
            'origin': job.origin
        })
    return JsonResponse({'queue': queue_name, 'jobs': results})
